var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var r=root.GetComponent<Character.Control.PaddleCharacterVisual>();float gap=0,drift=0,widthError=0;UnityEngine.Vector3 localL=UnityEngine.Vector3.zero,localR=UnityEngine.Vector3.zero;
 var field=typeof(Character.Control.PaddleCharacterVisual).GetField("baseVertices",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);
 UnityEngine.Vector3 MeshPixel(UnityEngine.SpriteRenderer sr,UnityEngine.Vector2 pixel){
  var originals=(System.Collections.Generic.Dictionary<UnityEngine.SpriteRenderer,UnityEngine.Vector2[]>)field.GetValue(r);var ov=originals[sr];var nv=sr.sprite.vertices;var tri=sr.sprite.triangles;int i=tri[0],j=tri[1],k=tri[2];
  var point=new UnityEngine.Vector2(pixel.x-sr.sprite.pivot.x,sr.sprite.rect.height-pixel.y-sr.sprite.pivot.y)/sr.sprite.pixelsPerUnit;
  var a=ov[j]-ov[i];var b=ov[k]-ov[i];var d=point-ov[i];float det=a.x*b.y-a.y*b.x;
  float v=(d.x*b.y-d.y*b.x)/det,w=(a.x*d.y-a.y*d.x)/det;
  return sr.transform.TransformPoint(nv[i]+v*(nv[j]-nv[i])+w*(nv[k]-nv[i]));
 }
 for(int n=0;n<1;n++){
  var q=UnityEngine.Quaternion.Euler(0,0,n%360);r.tool.rotation=q;r.tool.position=r.body.position+q*new UnityEngine.Vector3(new[]{.75f,1.35f,1.975f}[n/360],.074f,0);r.Pose();
  var renderers=root.GetComponentsInChildren<UnityEngine.SpriteRenderer>();
  var ul=renderers.First(x=>x.name=="Connected upper "+r.leftUpper.name);var ur=renderers.First(x=>x.name=="Connected upper "+r.rightUpper.name);
  var fl=renderers.First(x=>x.name=="Forearm segment "+r.leftLower.name);var fr=renderers.First(x=>x.name=="Forearm segment "+r.rightLower.name);
  UnityEngine.Debug.Log("UL="+MeshPixel(ul,new UnityEngine.Vector2(68,70))+" FL="+MeshPixel(fl,new UnityEngine.Vector2(13,17))+" UR="+MeshPixel(ur,new UnityEngine.Vector2(12,74))+" FR="+MeshPixel(fr,new UnityEngine.Vector2(12,28)));
  gap=UnityEngine.Mathf.Max(gap,UnityEngine.Vector3.Distance(MeshPixel(ul,new UnityEngine.Vector2(68,70)),MeshPixel(fl,new UnityEngine.Vector2(13,17))),UnityEngine.Vector3.Distance(MeshPixel(ur,new UnityEngine.Vector2(12,74)),MeshPixel(fr,new UnityEngine.Vector2(12,28))));
  var l=r.paddle.transform.InverseTransformPoint(r.LeftHand);var rr=r.paddle.transform.InverseTransformPoint(r.RightHand);if(n==0){localL=l;localR=rr;}else drift=UnityEngine.Mathf.Max(drift,UnityEngine.Vector3.Distance(l,localL),UnityEngine.Vector3.Distance(rr,localR));
  var originals=(System.Collections.Generic.Dictionary<UnityEngine.SpriteRenderer,UnityEngine.Vector2[]>)field.GetValue(r);
  foreach(var pair in new[]{(ul,new UnityEngine.Vector2(52,-54)),(ur,new UnityEngine.Vector2(-54,-58)),(fl,new UnityEngine.Vector2(-68,-1)),(fr,new UnityEngine.Vector2(-75,-13))}){
   var normal=new UnityEngine.Vector2(-pair.Item2.y,pair.Item2.x).normalized;var ov=originals[pair.Item1];var nv=pair.Item1.sprite.vertices;
   for(int i=0;i<nv.Length;i++)widthError=UnityEngine.Mathf.Max(widthError,UnityEngine.Mathf.Abs(UnityEngine.Vector2.Dot(nv[i]-ov[i],normal)));
  }
 }
 string log="1080 actual mesh poses: max elbow seam="+gap+" fixed paddle-local target drift="+drift+" cross-section change="+widthError;
 System.IO.File.WriteAllText("scripts/player-tail-connected-20261111/mesh-check.txt",log);UnityEngine.Debug.Log(log);
 if(gap>.001f||drift>.00001f||widthError>.00001f)throw new System.Exception("Connected arm regression");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
